        Scanner scanner = new Scanner(System.in);

        String str = scanner.nextLine();
        int a = Integer.parseInt(str);
        String aModStr = str.replace("0", "");
        int aMod = aModStr.isEmpty() ? 0 : Integer.parseInt(aModStr);

