        int c = a + b;
        String cStr = String.valueOf(c).replace("0", "");
        int cMod = cStr.isEmpty() ? 0 : Integer.parseInt(cStr);

        if (aMod + bMod == cMod) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }

        scanner.close();
    }
}

